import com.android.tools.smali.dexlib2.*;import com.android.tools.smali.dexlib2.iface.*;import com.android.tools.smali.dexlib2.iface.instruction.*;import java.io.*;
public class FindRefs {public static void main(String[] a)throws Exception{var d=DexFileFactory.loadDexContainer(new File(a[0]),Opcodes.forApi(26));for(var en:d.getDexEntryNames())for(var c:d.getEntry(en).getDexFile().getClasses())for(var m:c.getMethods()){if(m.getImplementation()==null)continue;for(var i:m.getImplementation().getInstructions())if(i instanceof ReferenceInstruction r&&r.getReference().toString().matches(a[1]))System.out.println(m+" => "+r.getReference());}}}
